/**
 * chinesePinyin.js
 * Chinesisch ist eine Wortschrift (Hanzi): jedes Zeichen steht für eine
 * Silbe/Morphem, es gibt keine feste Buchstaben-Laut-Zuordnung wie bei
 * Alphabet- oder Abugida-Schriften.
 *
 * Diese Tabelle deckt 14.411 einzelne Hanzi ab: die ursprüngliche,
 * vom Nutzer bereitgestellte Basistabelle (8.105 Zeichen, Herkunft/Lizenz
 * ungeklärt - siehe TODO unten) plus eine Ergänzung um 6.306 zusätzliche
 * Zeichen (v. a. traditionelle Schriftzeichen sowie seltenere Varianten),
 * automatisch extrahiert aus CC-CEDICT (aktueller offizieller
 * MDBG-Export, CC BY-SA 4.0 - siehe data/CHINESISCH_WORTLISTE_LIZENZ.md,
 * dieselbe Quelle wie die Wortliste in chineseWordSegmentation.js). Bei
 * Überschneidungen hat die ursprüngliche Basistabelle Vorrang; die
 * CC-CEDICT-Ergänzung steht als eigener, gekennzeichneter Block am Ende
 * der Datei und enthält nur Zeichen, die vorher fehlten.
 *
 * Nicht gelistete Zeichen werden unverändert durchgereicht und
 * anschließend vom finalen ASCII-Sicherheitsnetz (asciiSanitizer.js)
 * entfernt - die Ausgabe bleibt also garantiert ASCII, Lücken bei sehr
 * seltenen/exotischen Zeichen sind aber weiterhin möglich.
 *
 * WICHTIGE EINSCHRÄNKUNG (Polyphone): Jedes Zeichen hat hier genau EINE
 * hinterlegte Lesung (die häufigste/Standardlesung), auch wenn viele
 * Hanzi je nach Wort/Kontext unterschiedlich ausgesprochen werden (z. B.
 * 了 als "le" vs. "liao", 长 als "chang" vs. "zhang", 行 als "hang" vs.
 * "xing"). Es findet KEINE wörterbuchbasierte Mehrzeichen-Erkennung
 * statt (anders als z. B. bei Khmer/Arabisch in diesem Projekt) - jedes
 * Zeichen wird unabhängig vom Kontext nachgeschlagen. Das ist eine
 * bewusste Vereinfachung, keine vollständige Polyphon-Disambiguierung.
 *
 * Töne werden weiterhin bewusst nicht kodiert (weder als Diakritika noch
 * als Tonziffern), da am Ende ohnehin nur reines ASCII ausgegeben wird.
 *
 * TODO Herkunft/Lizenz: Diese Tabelle wurde vom Nutzer als fertige Liste
 * bereitgestellt (export_const_CHINESISCH_PINYIN_MAP.txt). Quelle und
 * Lizenz sind noch zu klären und hier zu dokumentieren, bevor das Projekt
 * (analog zu den Lizenzhinweisen bei Khmer/Arabisch/Lao/Koptisch)
 * veröffentlicht wird.
 */

